@using RecipeCommunity.Models

<PageTitle>Recipe Community</PageTitle>

<h1>🍳 Recipe Community</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in RecipeStore.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">@RecipeStore.GetByCategory(category).Count recipe(s)</p>
                    <a href="@($"recipes/{category.ToLower()}")" class="btn btn-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
